-- New private read-only authority fingerprint; no installer/profile seed.
-- Call after the complete catalogue fence and permanent-XID drain, before
-- trusting any source graph. Data rows and sequence positions are excluded.
create function cp7_global_nonpo_envelope.catalogue_fingerprint_v1()returns jsonb
language sql stable security definer set search_path=''set TimeZone='UTC'as $catalogue$
 with observations as(
select 'aggregates'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select p.oid::regprocedure::text,to_jsonb(a)from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_aggregate a on a.aggfnoid=p.oid where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'casts'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select c.castsource::regtype::text||'->'||c.casttarget::regtype::text,
 jsonb_build_array(c.castcontext::text,c.castmethod::text,c.castfunc::regprocedure::text)
 from pg_cast c)q(k,v)
 union all
select 'columns'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||c.relname||':'||a.attname,jsonb_build_array(a.attname,row_number()over(partition by c.oid order by a.attnum),format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attstorage,a.attcompression,a.attstattarget,a.attoptions,a.attfdwoptions,a.attcollation::regcollation::text,a.attacl::text[],pg_get_expr(d.adbin,d.adrelid))from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attnum>0 and not a.attisdropped and n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'constraints'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||coalesce(c.relname,t.typname)||':'||k.conname,jsonb_build_array(k.contype,k.condeferrable,k.condeferred,k.convalidated,k.conislocal,k.coninhcount,k.connoinherit,(select pn.nspname||'.'||pc.relname||':'||pk.conname from pg_constraint pk join pg_class pc on pc.oid=pk.conrelid join pg_namespace pn on pn.oid=pc.relnamespace where pk.oid=k.conparentid),case when k.conindid=0 then null else k.conindid::regclass::text end,c.oid::regclass::text,pg_get_constraintdef(k.oid,false))from pg_constraint k join pg_namespace n on n.oid=k.connamespace left join pg_class c on c.oid=k.conrelid left join pg_type t on t.oid=k.contypid where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'database_authority'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select 'CURRENT',jsonb_build_array(pg_get_userbyid(d.datdba),pg_encoding_to_char(d.encoding),d.datcollate,d.datctype,d.datconnlimit,d.datistemplate,d.datallowconn,(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(d.datacl,acldefault('d',d.datdba)))a),(select jsonb_agg(jsonb_build_array(case when s.setrole=0 then 'DATABASE'else pg_get_userbyid(s.setrole)end,encode(sha256(convert_to(s.setconfig::text,'UTF8')),'hex'))order by s.setrole)from pg_db_role_setting s where s.setdatabase=d.oid))from pg_database d where d.datname=current_database())q(k,v)
 union all
select 'default_privileges'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select pg_get_userbyid(d.defaclrole)||':'||coalesce(n.nspname,'GLOBAL')||':'||d.defaclobjtype::text,(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(d.defaclacl,acldefault('r',d.defaclrole)))a)from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or(n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_'))q(k,v)
 union all
select 'enums'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select t.oid::regtype::text||':'||e.enumsortorder::text,to_jsonb(e.enumlabel)from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'event_triggers'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select e.evtname,jsonb_build_array(e.evtevent,pg_get_userbyid(e.evtowner),e.evtfoid::regprocedure::text,e.evtenabled,e.evttags)from pg_event_trigger e)q(k,v)
 union all
select 'extensions'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select e.extname,jsonb_build_array(e.extversion,n.nspname,pg_get_userbyid(e.extowner),e.extrelocatable,(select jsonb_agg(r::regclass::text order by r::regclass::text)from unnest(e.extconfig)r),e.extcondition)from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname<>'pg_cron')q(k,v)
 union all
select 'functions'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select p.oid::regprocedure::text,jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),l.lanname,p.prokind,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,p.provolatile,p.proparallel,p.procost::text,p.prorows::text,p.proconfig,p.proargnames,p.proargmodes,pg_get_function_arguments(p.oid),pg_get_function_result(p.oid),p.prosupport::regprocedure::text,(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a))from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where p.prokind<>'a'and n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'indexes'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||c.relname,jsonb_build_array(pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready,i.indislive,i.indisclustered,i.indisreplident)from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'inheritance'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select i.inhrelid::regclass::text||':'||i.inhseqno::text,to_jsonb(i.inhparent::regclass::text)from pg_inherits i join pg_class c on c.oid=i.inhrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'languages'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select l.lanname,jsonb_build_array(pg_get_userbyid(l.lanowner),l.lanispl,l.lanpltrusted,
 l.lanplcallfoid::regprocedure::text,l.laninline::regprocedure::text,l.lanvalidator::regprocedure::text,
 case when l.lanacl is null then null else to_jsonb(array(select a::text from unnest(l.lanacl)a order by a::text collate "C"))end)
 from pg_language l)q(k,v)
 union all
select 'memberships'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select pg_get_userbyid(m.roleid)||':'||pg_get_userbyid(m.member)||':'||pg_get_userbyid(m.grantor),jsonb_build_array(m.admin_option,m.inherit_option,m.set_option)from pg_auth_members m)q(k,v)
 union all
select 'operators'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||o.oprname||'('||o.oprleft::regtype::text||','||o.oprright::regtype::text||')',
 jsonb_build_array(pg_get_userbyid(o.oprowner),o.oprkind::text,o.oprcanmerge,o.oprcanhash,
 o.oprleft::regtype::text,o.oprright::regtype::text,o.oprresult::regtype::text,
 o.oprcode::regprocedure::text,o.oprcom::regoperator::text,o.oprnegate::regoperator::text,
 o.oprrest::regprocedure::text,o.oprjoin::regprocedure::text)
 from pg_operator o join pg_namespace n on n.oid=o.oprnamespace)q(k,v)
 union all
select 'policies'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||c.relname||':'||p.polname,jsonb_build_array(p.polcmd,p.polpermissive,(select jsonb_agg(case when r=0 then 'PUBLIC'else pg_get_userbyid(r)end order by case when r=0 then 'PUBLIC'else pg_get_userbyid(r)end)from unnest(p.polroles)r),pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'relations'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||c.relname,jsonb_build_array(pg_get_userbyid(c.relowner),c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,c.relispartition,c.relreplident,c.reloptions,c.relispopulated,case when c.relkind in('v','m')then pg_get_viewdef(c.oid,false)else null end,pg_get_partkeydef(c.oid),pg_get_expr(c.relpartbound,c.oid),case when c.relkind='S'then (select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(c.relacl,acldefault('s',c.relowner)))a)else (select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a)end)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'roles'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select r.rolname,jsonb_build_array(r.rolsuper,r.rolinherit,r.rolcreaterole,r.rolcreatedb,r.rolcanlogin,r.rolreplication,r.rolbypassrls,r.rolconnlimit,r.rolvaliduntil::text,encode(sha256(convert_to(coalesce(r.rolconfig::text,''),'UTF8')),'hex'))from pg_roles r)q(k,v)
 union all
select 'rules'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||c.relname||':'||r.rulename,jsonb_build_array(r.ev_type,r.ev_enabled,r.is_instead,pg_get_ruledef(r.oid,false))from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'schemas'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname,jsonb_build_array(pg_get_userbyid(n.nspowner),(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner)))a))from pg_namespace n where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'sequence_ownership'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select c.oid::regclass::text,jsonb_build_array(d.deptype,d.refobjid::regclass::text,a.attname)from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_depend d on d.classid='pg_class'::regclass and d.objid=c.oid and d.refclassid='pg_class'::regclass and d.deptype in('a','i')left join pg_attribute a on a.attrelid=d.refobjid and a.attnum=d.refobjsubid where c.relkind='S'and n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'sequences'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select s.seqrelid::regclass::text,jsonb_build_array(format_type(s.seqtypid,null),s.seqstart::text,s.seqincrement::text,s.seqmax::text,s.seqmin::text,s.seqcache::text,s.seqcycle)from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'triggers'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select n.nspname||'.'||c.relname||':'||case when t.tgisinternal then k.conrelid::regclass::text||':'||k.conname||':'||t.tgfoid::regprocedure::text||':'||t.tgtype::text else t.tgname::text end,jsonb_build_array(t.tgisinternal,t.tgenabled,t.tgtype,t.tgnargs,encode(t.tgargs,'hex'),coalesce((select jsonb_agg(a.attname order by x.ord)from unnest(t.tgattr::smallint[])with ordinality x(attnum,ord)join pg_attribute a on a.attrelid=t.tgrelid and a.attnum=x.attnum),'[]'::jsonb),t.tgdeferrable,t.tginitdeferred,t.tgfoid::regprocedure::text,case when t.tgisinternal then null else pg_get_triggerdef(t.oid,false)end,t.tgoldtable,t.tgnewtable,k.conname,case when t.tgconstrrelid=0 then null else t.tgconstrrelid::regclass::text end,case when t.tgparentid=0 then null else (select p.tgname from pg_trigger p where p.oid=t.tgparentid)end,k.conrelid::regclass::text)from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace left join pg_constraint k on k.oid=t.tgconstraint where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'type_implementation'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select t.oid::regtype::text,jsonb_build_array(t.typlen,t.typbyval,t.typdelim,t.typalign,t.typstorage,t.typndims,t.typrelid::regclass::text,t.typelem::regtype::text,t.typarray::regtype::text,t.typsubscript::regprocedure::text,t.typinput::regprocedure::text,t.typoutput::regprocedure::text,t.typreceive::regprocedure::text,t.typsend::regprocedure::text,t.typmodin::regprocedure::text,t.typmodout::regprocedure::text,t.typanalyze::regprocedure::text)from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 union all
select 'types'::text name,coalesce(jsonb_agg(jsonb_build_array(k,v)order by k collate "C",v::text collate "C"),'[]'::jsonb)value from (select t.oid::regtype::text,jsonb_build_array(pg_get_userbyid(t.typowner),t.typtype,t.typcategory,t.typispreferred,t.typisdefined,t.typnotnull,case when t.typbasetype=0 then null else format_type(t.typbasetype,t.typtypmod)end,t.typdefault,t.typcollation::regcollation::text,(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable)order by a.grantee::regrole::text,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]'::jsonb)from aclexplode(coalesce(t.typacl,acldefault('t',t.typowner)))a))from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname<>all(array['pg_catalog','information_schema','cron']) and n.nspname!~'^pg_')q(k,v)
 ),combined as(select jsonb_object_agg(name,value)catalogues from observations)
 select jsonb_build_object('contract','cp7.global-catalogue-fingerprint.v1',
  'groups',25,'sha256',encode(sha256(convert_to(catalogues::text,'UTF8')),'hex'),
  'counts',(select jsonb_object_agg(name,jsonb_array_length(value))from observations))from combined
$catalogue$;
alter function cp7_global_nonpo_envelope.catalogue_fingerprint_v1()owner to postgres;
revoke all on function cp7_global_nonpo_envelope.catalogue_fingerprint_v1()from public,anon,authenticated,service_role;
